import type { Api } from '@/services/apiClient';

// The weekly FMS hours file (BPA-58; E2-08). React never calls Camunda; the file is generated by the backend and only downloaded here.

/** GET /api/v1/fms-hours-exports/{id}/file: the stored .xlsx as a blob (ppc-team only); null when the call failed. */
export async function downloadFmsHoursExport(api: Api, fmsHoursExportId: string): Promise<Blob | null> {
  try {
    const { data, response } = await api.GET('/api/v1/fms-hours-exports/{fmsHoursExportId}/file', {
      params: { path: { fmsHoursExportId } },
      parseAs: 'blob',
    });
    return response.ok && data ? (data as Blob) : null;
  } catch {
    return null;
  }
}
